"""Largest-remainder allocation of an amount in cents. See task.md."""

from __future__ import annotations


def _is_int(value: object) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def allocate(amount: int, weights: list[int]) -> list[int]:
    """Split `amount` cents in proportion to `weights`, one share per weight."""
    if not _is_int(amount) or amount < 0:
        raise ValueError("amount must be a non-negative int")

    weights = list(weights)
    if not weights:
        raise ValueError("weights must not be empty")
    for weight in weights:
        if not _is_int(weight) or weight < 0:
            raise ValueError("weights must be non-negative ints")

    total = sum(weights)
    if total == 0:
        raise ValueError("at least one weight must be positive")

    shares = [amount * weight // total for weight in weights]
    leftover = amount - sum(shares)
    by_remainder = sorted(
        range(len(weights)),
        key=lambda i: (-(amount * weights[i] % total), i),
    )
    for i in by_remainder[:leftover]:
        shares[i] += 1
    return shares
